package checker

import (
    "context"
    "sync"
)

type Result struct {
    URL string
    Err error
}

func check(ctx context.Context, url string) error {
    select {
    case <-ctx.Done():
        return ctx.Err()
    default:
        return nil
    }
}

func CheckAll(ctx context.Context, urls []string, limit int) []Result {
    if limit < 1 {
        limit = 1
    }
    semaphore := make(chan struct{}, limit)
    results := make(chan Result)
    var wg sync.WaitGroup

    for _, url := range urls {
        url := url
        wg.Add(1)
        go func() {
            defer wg.Done()
            select {
            case semaphore <- struct{}{}:
                defer func() { <-semaphore }()
            case <-ctx.Done():
                results <- Result{URL: url, Err: ctx.Err()}
                return
            }
            results <- Result{URL: url, Err: check(ctx, url)}
        }()
    }

    go func() {
        wg.Wait()
        close(results)
    }()

    collected := make([]Result, 0, len(urls))
    for result := range results {
        collected = append(collected, result)
    }
    return collected
}
